UPDATE ma
SET ma.url = j.url
FROM media_assets ma
JOIN exercise_media em ON em.media_asset_id = ma.id
JOIN exercises e ON e.id = em.exercise_id
JOIN OPENJSON(@pairs) WITH (code NVARCHAR(10) '$.code', url NVARCHAR(500) '$.url') AS j
    ON e.code = j.code;
